#!/usr/bin/env node
import { createHash } from 'node:crypto';
import { lstatSync, readFileSync, readdirSync } from 'node:fs';
import { join, relative, resolve, sep } from 'node:path';
const REPO='Labpics-Team/agents-config', COMMIT='1099dd68ce3ad697274bc2ea707837607b60283c', EXPECTED=[".github/actions/code-admission/action.yml","architecture/git.mjs","architecture/model.mjs","plans/tools/code-admission.mjs","plans/tools/code-admission/controls.mjs","plans/tools/code-admission/identity.mjs","plans/tools/code-admission/install-tools.sh","plans/tools/code-admission/qualify-ast-grep.mjs","plans/tools/code-admission/qualify-trivy.mjs","plans/tools/code-admission/reject-symlinks.sh","plans/tools/code-admission/rules.json","plans/tools/code-admission/snapshot.mjs","plans/tools/code-admission/trivy.mjs"];
function walk(root,dir=root){const out=[];for(const e of readdirSync(dir,{withFileTypes:true})){const a=join(dir,e.name),s=lstatSync(a);if(s.isSymbolicLink())throw Error('Carrier symlinks are forbidden');if(s.isDirectory())out.push(...walk(root,a));else if(s.isFile())out.push(relative(root,a).split(sep).join('/'));else throw Error('Unsupported carrier entry');}return out;}
const blobId=b=>createHash('sha1').update(`blob ${b.length}\0`).update(b).digest('hex');
function main(argv){if(argv.length!==2||argv[0]!=='--root')throw TypeError('usage: verify.mjs --root DIRECTORY');const root=resolve(argv[1]),r=JSON.parse(readFileSync(join(root,'source.json'),'utf8'));if(r?.schema!=='labpics.code-admission/public-carrier/v1'||r.sourceRepository!==REPO||r.sourceCommit!==COMMIT||!Array.isArray(r.files)||r.files.length!==EXPECTED.length)throw Error('Carrier origin receipt is invalid');const exp=new Set(EXPECTED),seen=new Set();for(const i of r.files){if(!i||!exp.has(i.path)||seen.has(i.path)||!/^[a-f0-9]{40}$/.test(i.blob))throw Error('Carrier receipt member is invalid');seen.add(i.path);const a=join(root,i.path),s=lstatSync(a);if(!s.isFile()||s.isSymbolicLink())throw Error('Carrier member is not a regular file');if(blobId(readFileSync(a))!==i.blob)throw Error('Carrier drift: '+i.path);}const actual=walk(root).sort(),required=[...EXPECTED,'source.json','verify.mjs'].sort();if(JSON.stringify(actual)!==JSON.stringify(required))throw Error('Carrier contains missing or unexpected files');console.log(JSON.stringify({repository:REPO,commit:COMMIT,files:EXPECTED.length}));}
try{main(process.argv.slice(2));}catch(e){console.error(String(e.message).replace(/[\x00-\x1f\x7f]/g,' '));process.exitCode=2;}
